 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])

    # Find the three-row color key: a repeated horizontal run.
    key = None
    key_cells = set()
    for r in range(H - 2):
        for c in range(W):
            if g[r][c] == 0:
                continue
            end = c
            while end < W and g[r][end] != 0:
                end += 1
            seq = g[r][c:end]
            if len(seq) < 2 or end > W:
                continue
            if all(g[rr][c:end] == seq for rr in (r + 1, r + 2)):
                key = seq
                key_cells = {(rr, cc) for rr in range(r, r + 3) for cc in range(c, end)}
                break
        if key is not None:
            break
    if key is None:
        return g

    # Find separate colored components belonging to the key colors, excluding the key itself.
    seen = set()
    components = {color: [] for color in key}
    for r in range(H):
        for c in range(W):
            color = g[r][c]
            if color == 0 or color not in components or (r, c) in key_cells or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < H and 0 <= nx < W and (ny,nx) not in seen
                            and (ny,nx) not in key_cells and g[ny][nx] == color):
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components[color].append(cells)

    # The earliest key color already used for a motif supplies its shape and stack position.
    source_index = next((i for i, color in enumerate(key) if components[color]), None)
    if source_index is None:
        return g
    source = components[key[source_index]][0]
    min_r = min(r for r, c in source)
    max_r = max(r for r, c in source)
    min_c = min(c for r, c in source)
    max_c = max(c for r, c in source)
    h = max_r - min_r + 1
    mask = {(r - min_r, c - min_c) for r, c in source}
    top = min_r - source_index * h

    # Remove key and existing colored motif copies, then paint the complete ordered stack.
    for r, c in key_cells:
        g[r][c] = 0
    for color in key:
        for comp in components[color]:
            for r, c in comp:
                g[r][c] = 0
    for i, color in enumerate(key):
        y0 = top + i * h
        for dy, dx in mask:
            y, x = y0 + dy, min_c + dx
            if 0 <= y < H and 0 <= x < W:
                g[y][x] = color
    return g
